      }

      words[w] = glyph;
      words[w + 1] = fg;
      words[w + 2] = bg;

      // Floyd–Steinberg: 7/16 right, 3/16 below left, 5/16 below, 1/16 below right.
      if (onLattice && !isFlat && t[3]! > N * EDGE * 0.5) {
