export function strips(
  words: Uint32Array,
  columns: number,
  rows: number,
): { rows: number; cells: string }[] {
  const count = Math.ceil((columns * rows) / PAIRS);
  const each = Math.max(1, Math.min(Math.ceil(rows / count), Math.floor(PAIRS / columns)));
