  for (let top = 0; top < rows; top += each) {
    const n = Math.min(each, rows - top);
    const part = words.subarray(top * columns * 3, (top + n) * columns * 3);
    out.push({
      rows: n,
      cells: new Uint8Array(part.buffer, part.byteOffset, part.byteLength).toBase64(),
    });
  }

  return out;
}

